// Pixel Spider animation catalogue.
// Strips live in public/mascot/v2/<name>.png (frames of 256x256 side by side) and are
// generated by scripts/mascot/build_frames_v2.py together with anims.json.

export type AnimName =
  | 'idle'
  | 'blink'
  | 'look-left'
  | 'look-right'
  | 'walk'
  | 'hop'
  | 'dance'
  | 'wave'
  | 'typing'
  | 'sleep'
  | 'love'
  | 'dizzy'
  | 'surprised'
  | 'annoyed'
  | 'dangle'
  | 'fall'
  | 'land'
  | 'celebrate'
  | 'loading';

export interface AnimMeta {
  frames: number;
  fps: number;
  loop: boolean;
}

export const ANIM_NAMES: AnimName[] = [
  'idle', 'blink', 'look-left', 'look-right', 'walk', 'hop', 'dance', 'wave', 'typing', 'sleep',
  'love', 'dizzy', 'surprised', 'annoyed', 'dangle', 'fall', 'land', 'celebrate', 'loading',
];

// Mirrors public/mascot/v2/anims.json; the component loads that file and falls back to this copy.
export const DEFAULT_ANIMS: Record<AnimName, AnimMeta> = {
  idle: { frames: 4, fps: 4, loop: true },
  blink: { frames: 1, fps: 1, loop: false },
  'look-left': { frames: 1, fps: 1, loop: false },
  'look-right': { frames: 1, fps: 1, loop: false },
  walk: { frames: 8, fps: 10, loop: true },
  hop: { frames: 6, fps: 14, loop: false },
  dance: { frames: 8, fps: 8, loop: true },
  wave: { frames: 6, fps: 8, loop: true },
  typing: { frames: 4, fps: 10, loop: true },
  sleep: { frames: 4, fps: 3, loop: true },
  love: { frames: 6, fps: 8, loop: true },
  dizzy: { frames: 6, fps: 10, loop: true },
  surprised: { frames: 3, fps: 12, loop: false },
  annoyed: { frames: 4, fps: 6, loop: true },
  dangle: { frames: 4, fps: 6, loop: true },
  fall: { frames: 2, fps: 10, loop: true },
  land: { frames: 3, fps: 14, loop: false },
  celebrate: { frames: 4, fps: 8, loop: true },
  loading: { frames: 4, fps: 8, loop: true },
};

// Moods other parts of the OS can ask for through MascotContext (setFrame / react).
// The first eight are the original names; the rest map 1:1 onto new animations.
export type SpiderFrame =
  | 'idle'
  | 'blink'
  | 'loading'
  | 'celebrating'
  | 'sleeping'
  | 'typing'
  | 'waving'
  | 'swinging'
  | 'dance'
  | 'love'
  | 'dizzy'
  | 'annoyed'
  | 'surprised';

export const MOOD_TO_ANIM: Record<SpiderFrame, AnimName> = {
  idle: 'idle',
  blink: 'blink',
  loading: 'loading',
  celebrating: 'celebrate',
  sleeping: 'sleep',
  typing: 'typing',
  waving: 'wave',
  swinging: 'dangle',
  dance: 'dance',
  love: 'love',
  dizzy: 'dizzy',
  annoyed: 'annoyed',
  surprised: 'surprised',
};

export const isAnimMeta = (v: unknown): v is AnimMeta => {
  if (!v || typeof v !== 'object') return false;
  const m = v as Record<string, unknown>;
  return typeof m.frames === 'number' && m.frames >= 1 && typeof m.fps === 'number' && m.fps > 0 && typeof m.loop === 'boolean';
};

// Where things are inside a 256px frame (fractions, so they scale with the display size).
export const SPRITE_GEOMETRY = {
  headTop: 18 / 256, // top of the hair
  feet: 236 / 256, // bottom of the feet
  centerX: 127 / 256,
};
